fn concatenate(a: Vec<f32>, b: Vec<f32>) -> Vec<f32> {
    // Pre-allocate the exact needed capacity to avoid re-allocations.
    let mut result = Vec::with_capacity(a.len() + b.len());
    // Move all elements from `a` into `result`.
    result.extend(a);
    // Move all elements from `b` into `result`.
    result.extend(b);
    result
}

